  static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var x in All(child))yield return x;}
  static void Layout(Control c){c.PerformLayout();foreach(Control child in c.Controls)Layout(child);}
  static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
  static object Field(object o,string n){return o.GetType().GetField(n,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(o);}
  static void Call(object o,string n){o.GetType().GetMethod(n,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(o,null);}
  static void WaitFor(Func<bool> condition){DateTime end=DateTime.UtcNow.AddSeconds(8);while(!condition()){if(DateTime.UtcNow>end)throw new Exception("Timed out waiting for local API/UI");Application.DoEvents();System.Threading.Thread.Sleep(15);}}
  static void PumpBriefly(){DateTime end=DateTime.UtcNow.AddMilliseconds(350);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
  static void Respond(System.Threading.Tasks.Task<System.Net.HttpListenerContext> request,Notice notice,string expected,string reply){notice.Opacity=0;WaitFor(()=>request.IsCompleted);var ctx=request.Result;string body;using(var reader=new StreamReader(ctx.Request.InputStream))body=reader.ReadToEnd();Check(body.Contains(expected),"correct encouragement trigger: "+expected);byte[] bytes=System.Text.Encoding.UTF8.GetBytes(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{choices=new[]{new{message=new{content=reply}}}}));ctx.Response.ContentLength64=bytes.Length;ctx.Response.OutputStream.Write(bytes,0,bytes.Length);ctx.Response.Close();WaitFor(()=>notice.Detail.Text.Contains(reply));}
  static void Render(Form form,string file){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();Layout(form);using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(file);}Console.WriteLine(Path.GetFileName(file)+" DPI="+form.CurrentAutoScaleDimensions+" size="+form.Size);foreach(var label in All(form).OfType<Label>().Where(l=>l.Visible&&l.Font.Size>=14)){using(var g=label.CreateGraphics())Check(label.Height>=label.Font.GetHeight(g),"Clipped large label: "+label.Text+" height="+label.Height+" needed="+label.Font.GetHeight(g)+" font="+label.Font.Size);}foreach(var b in All(form).OfType<Button>().Where(b=>b.Visible&&b.Parent is FlowLayoutPanel))Check(b.Bottom<=b.Parent.ClientSize.Height&&b.Right<=b.Parent.ClientSize.Width,"Clipped flow button: "+b.Text);form.Hide();}
