    engine.Stop(DateTime.UtcNow,"测试结束");Call(form,"DeleteSelected");Check(engine.Current.Deleted,"active-list deletion tombstone");Check(store.Load().Records.Count==0,"delete purges logs");mini.Close();
   }}
   var completeStore=new Store(Path.Combine(dir,"delete-completed-"+Guid.NewGuid().ToString("N")));var doneData=new AppData{Sound=false};doneData.Projects.Add(new Project{Name="已完成",Completed=true});completeStore.Save(doneData);using(var form=new MainForm(completeStore)){form.Opacity=0;form.Show();((RadioButton)Field(form,"completedView")).Checked=true;Call(form,"DeleteSelected");Check(completeStore.Load().Projects[0].Deleted,"completed task deletion supported");}
  }
 }
